  INDEX `bid_bidding_bid_publish_datetime_IDX`(`bid_publish_datetime` ASC) USING BTREE,
  INDEX `bid_bidding_begin_date_IDX`(`begin_date` ASC, `end_date` ASC) USING BTREE
