-- ----------------------------
-- Table structure for tmp_energy_consume
-- ----------------------------
DROP TABLE IF EXISTS `tmp_energy_consume`;
CREATE TABLE `tmp_energy_consume`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `type` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '类型：0消耗1节约',
  `category` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '分类：1电2水',
  `month` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '月份',
  `day` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '日期',
  `energy` double NULL DEFAULT NULL COMMENT '能耗数或节约数',
  `item_category` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '项目类型',
  `year` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '年份',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `type_2`(`type` ASC, `category` ASC) USING BTREE,
  INDEX `type`(`type` ASC, `category` ASC, `item_category` ASC, `month` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 890 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '能耗临时表' ROW_FORMAT = DYNAMIC;

