-- Records of tmp_energy_consume
-- ----------------------------

-- ----------------------------
-- Table structure for wms_carrier_apply
-- ----------------------------
DROP TABLE IF EXISTS `wms_carrier_apply`;
CREATE TABLE `wms_carrier_apply`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `serial_no` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '流水号',
  `customer_id` bigint NULL DEFAULT NULL COMMENT '客户id',
  `apply_user` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '申请人',
  `apply_time` datetime NULL DEFAULT NULL COMMENT '申请日期',
  `apply_status` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '申请状态：0未提交1待审核',
  `audit_user` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '审核人',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核日期',
  `audit_status` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '审核状态：0审核未通过1审核通过',
  `out_warehouse_id` bigint NULL DEFAULT NULL COMMENT '出库单id',
  `out_warehouse_no` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '出库单流水号',
  `sale_delivery_id` bigint NULL DEFAULT NULL COMMENT '销售发货单id',
  `sale_delivery_no` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '销售发货单流水号',
  `shipping_address` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '收货地址',
  `contact` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '联系人',
  `contact_tel` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `carrier_user` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '承运人',
  `distance` double NULL DEFAULT NULL COMMENT '运输距离',
  `remark` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '备注',
  `audit_comment` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '审核意见',
  `delivery_date` date NULL DEFAULT NULL COMMENT '交货日期',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 66 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '产品承运申请' ROW_FORMAT = DYNAMIC;

