-- ----------------------------
-- Table structure for wms_warehouse_check
-- ----------------------------
DROP TABLE IF EXISTS `wms_warehouse_check`;
CREATE TABLE `wms_warehouse_check`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `serial_no` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '流水号',
  `material_id` bigint NULL DEFAULT NULL COMMENT '物料编号',
  `warehouse_id` bigint NULL DEFAULT NULL COMMENT '仓库编号',
  `wh_region_id` bigint NULL DEFAULT NULL COMMENT '库区编号',
  `wh_location_id` bigint NULL DEFAULT NULL COMMENT '库位编号',
  `batch_no` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '批号',
  `check_type` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '盘点类型：1盘盈0盘亏',
  `stock_month` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '库存月份',
  `check_date` date NULL DEFAULT NULL COMMENT '盘点日期',
  `check_user` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '负责人',
  `inventory` double NULL DEFAULT NULL COMMENT '现库存',
  `actual_inventory` double NULL DEFAULT NULL COMMENT '实际库存',
  `reason` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '原因',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 57 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '盘点单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wms_warehouse_check
-- ----------------------------

-- ----------------------------
-- Table structure for wms_warehouse_location
-- ----------------------------
DROP TABLE IF EXISTS `wms_warehouse_location`;
CREATE TABLE `wms_warehouse_location`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '编码',
  `region_id` bigint NULL DEFAULT NULL COMMENT '库区编码',
  `name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '库区名称',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 91 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '库位信息' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wms_warehouse_location
-- ----------------------------

-- ----------------------------
-- Table structure for wms_warehouse_material
-- ----------------------------
DROP TABLE IF EXISTS `wms_warehouse_material`;
CREATE TABLE `wms_warehouse_material`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `warehouse_id` bigint NULL DEFAULT NULL COMMENT '仓库编号',
  `material_id` bigint NULL DEFAULT NULL COMMENT '物料档案编号',
  `total_inventory` double NULL DEFAULT NULL COMMENT '总库存',
  `freeze_inventory` double NULL DEFAULT 0 COMMENT '锁定库存',
  `max_inventory` double NULL DEFAULT 0 COMMENT '库存上限',
  `min_inventory` double NULL DEFAULT 0 COMMENT '库存下限',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 92 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '仓库物料信息' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wms_warehouse_material
