-- ----------------------------
-- Table structure for wms_warehouse_material_detail
-- ----------------------------
DROP TABLE IF EXISTS `wms_warehouse_material_detail`;
CREATE TABLE `wms_warehouse_material_detail`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `wh_id` bigint NULL DEFAULT NULL COMMENT '仓库编号',
  `wh_region_id` bigint NULL DEFAULT NULL COMMENT '库区编号',
  `wh_location_id` bigint NULL DEFAULT NULL COMMENT '库位编号',
  `wh_material_id` bigint NULL DEFAULT NULL COMMENT '仓库物料编号',
  `serial_no` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '序列号',
  `product_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `manufacturer` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '生产厂家',
  `batch_no` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '生产批号',
  `inventory` double NULL DEFAULT NULL COMMENT '库存量',
  `lock_inventory` double NULL DEFAULT NULL COMMENT '锁定库存',
  `remark` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建日期',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改日期',
  `create_by` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '修改人',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 349 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '仓库物料明细' ROW_FORMAT = DYNAMIC;

