-- ----------------------------
-- View structure for v_mes_product_power_detail
-- ----------------------------
DROP VIEW IF EXISTS `v_mes_product_power_detail`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_mes_product_power_detail` AS select `t`.`plan_id` AS `plan_id`,`t`.`bom_id` AS `bom_id`,`t`.`order_id` AS `order_id`,`t`.`product_date` AS `product_date`,`t`.`material_id` AS `material_id`,`t`.`require_quantity` AS `require_quantity`,`t`.`product_quantity` AS `product_quantity`,`t`.`process_id` AS `process_id`,`t`.`product_line_id` AS `product_line_id`,`p`.`power_consume` AS `power_consume`,`p`.`process_name` AS `process_name`,(`t`.`product_quantity` * `p`.`power_consume`) AS `total_power_consume`,`f`.`product_line_name` AS `product_line_name`,`m`.`name` AS `material_name`,`m`.`model` AS `material_model`,`m`.`specification` AS `material_specification`,`m`.`unit` AS `material_unit` from (((`mes_product_schedule` `t` left join `mes_process_model` `p` on((`p`.`id` = `t`.`process_id`))) left join `mes_factory_model` `f` on((`f`.`id` = `t`.`product_line_id`))) left join `wms_material_info` `m` on((`m`.`id` = `t`.`material_id`)));

-- ----------------------------
-- View structure for v_mes_equipment_power_detail
-- ----------------------------
DROP VIEW IF EXISTS `v_mes_equipment_power_detail`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_mes_equipment_power_detail` AS select `t`.`equipment_id` AS `equipment_id`,`q`.`name` AS `equipment_name`,`p`.`plan_id` AS `plan_id`,`p`.`bom_id` AS `bom_id`,`p`.`order_id` AS `order_id`,`p`.`product_date` AS `product_date`,`p`.`material_id` AS `material_id`,`p`.`require_quantity` AS `require_quantity`,`p`.`product_quantity` AS `product_quantity`,`p`.`process_id` AS `process_id`,`p`.`product_line_id` AS `product_line_id`,`p`.`power_consume` AS `power_consume`,`p`.`process_name` AS `process_name`,`p`.`total_power_consume` AS `total_power_consume`,`p`.`product_line_name` AS `product_line_name` from ((`mes_factory_model_detail` `t` left join `mes_equipment` `q` on((`q`.`id` = `t`.`equipment_id`))) left join `v_mes_product_power_detail` `p` on((`p`.`product_line_id` = `t`.`product_line_id`)));

-- ----------------------------
-- View structure for v_sale_contract_amount
-- ----------------------------
DROP VIEW IF EXISTS `v_sale_contract_amount`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_sale_contract_amount` AS select date_format(str_to_date(`sale_contract`.`sign_date`,'%m/%d/%Y'),'%Y-%m') AS `sign_date`,sum(`sale_contract`.`contract_amount`) AS `contract_amount` from (`sale_customer` join `sale_contract` on((`sale_customer`.`id` = `sale_contract`.`customer_id`))) group by `sale_contract`.`sign_date`;

-- ----------------------------
-- View structure for v_sale_contract_sale_amount
-- ----------------------------
DROP VIEW IF EXISTS `v_sale_contract_sale_amount`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_sale_contract_sale_amount` AS select date_format(str_to_date(`sale_contract`.`sign_date`,'%m/%d/%Y'),'%Y-%m') AS `sign_date`,sum(`sale_contract`.`contract_amount`) AS `total_contract_amount`,(sum(`sale_order`.`order_amount`) - sum(`sale_return`.`return_amount`)) AS `total_sale_amount` from (((`sale_customer` join `sale_order` on((`sale_customer`.`id` = `sale_order`.`customer_id`))) join `sale_contract` on((`sale_order`.`order_no` = `sale_contract`.`order_no`))) left join `sale_return` on((`sale_contract`.`contract_no` = `sale_return`.`contract_no`))) group by date_format(str_to_date(`sale_contract`.`sign_date`,'%m/%d/%Y'),'%Y-%m');

-- ----------------------------
-- View structure for v_scm_purchase_arrive_detail
-- ----------------------------
DROP VIEW IF EXISTS `v_scm_purchase_arrive_detail`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_scm_purchase_arrive_detail` AS select `a`.`contract_no` AS `contract_no`,`a`.`supplier_id` AS `supplier_id`,`d`.`arrive_id` AS `arrive_id`,`s`.`name` AS `supplier_name`,`d`.`material_id` AS `material_id`,`m`.`name` AS `material_name`,`m`.`code` AS `material_code`,`m`.`model` AS `material_model`,`m`.`specification` AS `material_specification`,`m`.`unit` AS `material_unit`,`d`.`batch_no` AS `batch_no`,`d`.`price` AS `price`,`d`.`arrive_quantity` AS `arrive_quantity`,`d`.`return_quantity` AS `return_quantity`,(`d`.`arrive_quantity` - `d`.`return_quantity`) AS `in_warehouse_quantity` from (((`scm_purchase_arrive_detail` `d` join `scm_purchase_arrive` `a` on((`a`.`id` = `d`.`arrive_id`))) left join `wms_material_info` `m` on((`m`.`id` = `d`.`material_id`))) left join `scm_purchase_supplier` `s` on((`s`.`id` = `a`.`supplier_id`)));

-- ----------------------------
-- View structure for v_scm_purchase_contract
-- ----------------------------
DROP VIEW IF EXISTS `v_scm_purchase_contract`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_scm_purchase_contract` AS select `pc`.`id` AS `contract_id`,`pc`.`contract_no` AS `contract_no`,`pc`.`supplier_id` AS `supplier_id`,`pc`.`apply_id` AS `apply_id`,`pc`.`apply_no` AS `apply_no`,`s`.`name` AS `supplier_name`,ifnull(`pc`.`amount`,0) AS `contract_amount`,date_format(`pc`.`sign_date`,'%Y') AS `contract_year`,quarter(`pc`.`sign_date`) AS `contract_quarter`,month(`pc`.`sign_date`) AS `contract_month`,date_format(`pc`.`sign_date`,'%Y-%m') AS `contract_year_month`,date_format(`pc`.`sign_date`,'%Y-%m-%d') AS `contract_date` from (`scm_purchase_contract` `pc` left join `scm_purchase_supplier` `s` on((`pc`.`supplier_id` = `s`.`id`))) where (`pc`.`audit_status` = '1');

-- ----------------------------
-- View structure for v_scm_purchase_contract_detail
-- ----------------------------
DROP VIEW IF EXISTS `v_scm_purchase_contract_detail`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_scm_purchase_contract_detail` AS select `cd`.`contract_id` AS `contract_id`,`cd`.`material_id` AS `material_id`,`m`.`name` AS `material_name`,`m`.`code` AS `material_code`,`m`.`model` AS `material_model`,`m`.`specification` AS `material_specification`,`m`.`unit` AS `material_unit`,`cd`.`price` AS `price`,`cd`.`quantity` AS `quantity`,`cd`.`amount` AS `amount`,`c`.`supplier_id` AS `supplier_id`,`s`.`name` AS `supplier_name`,`c`.`contract_no` AS `contract_no`,`c`.`sign_date` AS `sign_date` from (((`scm_purchase_contract_detail` `cd` left join `scm_purchase_contract` `c` on((`c`.`id` = `cd`.`contract_id`))) left join `scm_purchase_supplier` `s` on((`s`.`id` = `c`.`supplier_id`))) left join `wms_material_info` `m` on((`m`.`id` = `cd`.`material_id`)));

-- ----------------------------
-- View structure for v_scm_purchase_return_detail
-- ----------------------------
DROP VIEW IF EXISTS `v_scm_purchase_return_detail`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_scm_purchase_return_detail` AS select `rd`.`material_id` AS `material_id`,`rd`.`batch_no` AS `batch_no`,`rd`.`price` AS `price`,`rd`.`book_quantity` AS `book_quantity`,`rd`.`arrive_quantity` AS `arrive_quantity`,`rd`.`return_quantity` AS `return_quantity`,`m`.`name` AS `material_name`,`m`.`code` AS `material_code`,`m`.`model` AS `material_model`,`m`.`specification` AS `material_specification`,`m`.`unit` AS `material_unit`,`r`.`return_date` AS `return_date`,`r`.`return_no` AS `return_no`,`r`.`supplier_id` AS `supplier_id`,`s`.`name` AS `supplier_name` from (((`scm_purchase_return_detail` `rd` left join `scm_purchase_return` `r` on((`r`.`id` = `rd`.`return_id`))) left join `scm_purchase_supplier` `s` on((`s`.`id` = `r`.`supplier_id`))) left join `wms_material_info` `m` on((`m`.`id` = `rd`.`material_id`)));

-- ----------------------------
-- View structure for v_scm_sale_contract
-- ----------------------------
DROP VIEW IF EXISTS `v_scm_sale_contract`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_scm_sale_contract` AS select `sc`.`id` AS `contract_id`,`sc`.`contract_no` AS `contract_no`,`sc`.`order_id` AS `order_id`,`sc`.`order_no` AS `order_no`,`sc`.`customer_id` AS `customer_id`,`c`.`name` AS `customer_name`,ifnull(`sc`.`contract_amount`,0) AS `contract_amount`,date_format(`sc`.`sign_date`,'%Y') AS `contract_year`,quarter(`sc`.`sign_date`) AS `contract_quarter`,month(`sc`.`sign_date`) AS `contract_month`,date_format(`sc`.`sign_date`,'%Y-%m') AS `contract_year_month`,date_format(`sc`.`sign_date`,'%Y-%m-%d') AS `contract_date` from ((`scm_sale_contract` `sc` left join `scm_sale_order` `o` on((`sc`.`order_id` = `o`.`id`))) left join `scm_sale_customer` `c` on((`sc`.`customer_id` = `c`.`id`))) where (`sc`.`audit_status` = '1');

-- ----------------------------
-- View structure for v_scm_sale_contract_detail
-- ----------------------------
DROP VIEW IF EXISTS `v_scm_sale_contract_detail`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_scm_sale_contract_detail` AS select `cd`.`contract_id` AS `contract_id`,`c`.`contract_no` AS `contract_no`,`o`.`id` AS `order_id`,`o`.`order_no` AS `order_no`,`c`.`customer_id` AS `customer_id`,`c`.`contract_amount` AS `contract_amount`,`c`.`sign_date` AS `sign_date`,`sc`.`name` AS `customer_name`,`cd`.`material_id` AS `material_id`,`cd`.`price` AS `price`,`cd`.`quantity` AS `quantity`,`cd`.`amount` AS `amount`,`m`.`name` AS `material_name`,`m`.`model` AS `material_model`,`m`.`specification` AS `material_specification`,`m`.`unit` AS `material_unit` from ((((`scm_sale_contract_detail` `cd` left join `scm_sale_contract` `c` on((`c`.`id` = `cd`.`contract_id`))) left join `scm_sale_order` `o` on((`o`.`id` = `c`.`order_id`))) left join `wms_material_info` `m` on((`m`.`id` = `cd`.`material_id`))) left join `scm_sale_customer` `sc` on((`sc`.`id` = `c`.`customer_id`))) where (`c`.`audit_status` = '1');

-- ----------------------------
-- View structure for v_scm_sale_delivery_detail
-- ----------------------------
DROP VIEW IF EXISTS `v_scm_sale_delivery_detail`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_scm_sale_delivery_detail` AS select `sd`.`contract_no` AS `contract_no`,`d`.`delivery_id` AS `delivery_id`,`sd`.`customer_id` AS `customer_id`,`c`.`name` AS `customer_name`,`d`.`material_id` AS `material_id`,`m`.`name` AS `material_name`,`m`.`code` AS `material_code`,`m`.`model` AS `material_model`,`m`.`specification` AS `material_specification`,`m`.`unit` AS `material_unit`,`d`.`quantity` AS `quantity`,`d`.`return_quantity` AS `return_quantity` from (((`scm_sale_delivery_detail` `d` join `scm_sale_delivery` `sd` on((`sd`.`id` = `d`.`delivery_id`))) left join `wms_material_info` `m` on((`m`.`id` = `d`.`material_id`))) left join `scm_sale_customer` `c` on((`c`.`id` = `sd`.`customer_id`)));

-- ----------------------------
-- View structure for v_scm_sale_order
-- ----------------------------
DROP VIEW IF EXISTS `v_scm_sale_order`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_scm_sale_order` AS select `o`.`id` AS `order_id`,`o`.`order_no` AS `order_no`,`o`.`customer_id` AS `customer_id`,`c`.`name` AS `customer_name`,ifnull(`o`.`order_amount`,0) AS `order_amount`,date_format(`o`.`apply_time`,'%Y') AS `order_year`,quarter(`o`.`apply_time`) AS `order_quarter`,month(`o`.`apply_time`) AS `order_month`,date_format(`o`.`apply_time`,'%Y-%m') AS `order_year_month`,date_format(`o`.`apply_time`,'%Y-%m-%d') AS `order_date` from (`scm_sale_order` `o` left join `scm_sale_customer` `c` on((`o`.`customer_id` = `c`.`id`))) where (`o`.`audit_status` = '1');

-- ----------------------------
-- View structure for v_scm_sale_plan_detail
-- ----------------------------
DROP VIEW IF EXISTS `v_scm_sale_plan_detail`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_scm_sale_plan_detail` AS select `p`.`plan_no` AS `plan_no`,`p`.`title` AS `title`,`p`.`type` AS `type`,`p`.`start_date` AS `start_date`,`p`.`end_date` AS `end_date`,`d`.`sale_amount` AS `sale_amount`,`d`.`material_id` AS `material_id`,`m`.`name` AS `material_name` from ((`scm_sale_plan_detail` `d` join `scm_sale_plan` `p` on((`p`.`id` = `d`.`plan_id`))) left join `wms_material_info` `m` on((`m`.`id` = `d`.`material_id`)));

-- ----------------------------
-- View structure for v_wms_in_warehouse_detail
-- ----------------------------
DROP VIEW IF EXISTS `v_wms_in_warehouse_detail`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_wms_in_warehouse_detail` AS select `t`.`material_id` AS `material_id`,`t`.`batch_no` AS `batch_no`,`t`.`in_quantity` AS `in_quantity`,`t`.`warehouse_id` AS `wh_id`,`t`.`wh_region_id` AS `wh_region_id`,`t`.`wh_location_id` AS `wh_location_id`,`p`.`biz_type` AS `biz_type`,`p`.`apply_time` AS `in_wh_date`,`m`.`name` AS `material_name`,`m`.`model` AS `material_model`,`m`.`specification` AS `material_specification`,`m`.`unit` AS `material_unit`,`w`.`name` AS `wh_name`,`r`.`name` AS `wh_region_name`,`wl`.`name` AS `wh_location_name` from (((((`wms_in_warehouse_apply_detail` `t` left join `wms_in_warehouse_apply` `p` on((`p`.`id` = `t`.`apply_id`))) left join `wms_warehouse` `w` on((`w`.`id` = `t`.`warehouse_id`))) left join `wms_warehouse_region` `r` on((`r`.`id` = `t`.`wh_region_id`))) left join `wms_warehouse_location` `wl` on((`wl`.`id` = `t`.`wh_location_id`))) left join `wms_material_info` `m` on((`m`.`id` = `t`.`material_id`))) where (`p`.`bill_status` = '1');

-- ----------------------------
-- View structure for v_wms_material_inventory_detail
-- ----------------------------
DROP VIEW IF EXISTS `v_wms_material_inventory_detail`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_wms_material_inventory_detail` AS select `t`.`wh_id` AS `wh_id`,`t`.`wh_region_id` AS `wh_region_id`,`t`.`wh_location_id` AS `wh_location_id`,`t`.`inventory` AS `inventory`,`t`.`lock_inventory` AS `lock_inventory`,`t`.`batch_no` AS `batch_no`,`t`.`manufacturer` AS `manufacturer`,`wm`.`material_id` AS `material_id`,`wm`.`max_inventory` AS `max_inventory`,`wm`.`min_inventory` AS `min_inventory`,`m`.`name` AS `material_name`,`m`.`model` AS `material_model`,`m`.`specification` AS `material_specification`,`m`.`unit` AS `material_unit`,`w`.`name` AS `wh_name`,`r`.`name` AS `wh_region_name`,`wl`.`name` AS `wh_location_name` from (((((`wms_warehouse_material_detail` `t` left join `wms_warehouse_material` `wm` on((`wm`.`id` = `t`.`wh_material_id`))) left join `wms_warehouse` `w` on((`w`.`id` = `t`.`wh_id`))) left join `wms_warehouse_region` `r` on((`r`.`id` = `t`.`wh_region_id`))) left join `wms_warehouse_location` `wl` on((`wl`.`id` = `t`.`wh_location_id`))) left join `wms_material_info` `m` on((`m`.`id` = `wm`.`material_id`))) where (`t`.`wh_id` is not null);

-- ----------------------------
-- View structure for v_wms_out_warehouse_detail
-- ----------------------------
DROP VIEW IF EXISTS `v_wms_out_warehouse_detail`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_wms_out_warehouse_detail` AS select `t`.`material_id` AS `material_id`,`t`.`batch_no` AS `batch_no`,`t`.`out_quantity` AS `out_quantity`,`t`.`warehouse_id` AS `wh_id`,`t`.`wh_region_id` AS `wh_region_id`,`t`.`wh_location_id` AS `wh_location_id`,`p`.`biz_type` AS `biz_type`,`p`.`apply_time` AS `in_wh_date`,`m`.`name` AS `material_name`,`m`.`model` AS `material_model`,`m`.`specification` AS `material_specification`,`m`.`unit` AS `material_unit`,`w`.`name` AS `wh_name`,`r`.`name` AS `wh_region_name`,`wl`.`name` AS `wh_location_name` from (((((`wms_out_warehouse_apply_detail` `t` left join `wms_out_warehouse_apply` `p` on((`p`.`id` = `t`.`apply_id`))) left join `wms_warehouse` `w` on((`w`.`id` = `t`.`warehouse_id`))) left join `wms_warehouse_region` `r` on((`r`.`id` = `t`.`wh_region_id`))) left join `wms_warehouse_location` `wl` on((`wl`.`id` = `t`.`wh_location_id`))) left join `wms_material_info` `m` on((`m`.`id` = `t`.`material_id`))) where (`p`.`bill_status` = '3');

SET FOREIGN_KEY_CHECKS = 1;
